<?= $this->include('layout/header') ?><a class="btn" href="/products/new">Add Product</a><table><tr><th>Image</th><th>Name</th><th>Price</th><th>Stock</th><th>Actions</th></tr><?php foreach($products as $p): ?><tr><td><?php if($p['image']): ?><img class="thumb" src="/uploads/products/<?= esc($p['image']) ?>"><?php endif ?></td><td><?= esc($p['name']) ?></td><td>₱<?= number_format($p['price'],2) ?></td><td><?= esc($p['stock_quantity']) ?></td><td><a class="btn" href="/products/<?= $p['id'] ?>/edit">Edit</a><form style="display:inline" method="post" action="/products/<?= $p['id'] ?>/delete"><button class="btn danger">Delete</button></form></td></tr><?php endforeach ?></table><?= $this->include('layout/footer') ?>
